<script setup lang="ts">
import {ref,watch,nextTick} from 'vue';import type {CampusEvent,WorldSnapshot} from '../core/types.ts';import {clock,labels} from '../ui/format.ts';
const props=defineProps<{event:CampusEvent|null;help:boolean;world:WorldSnapshot}>();const emit=defineEmits<{close:[];event:[id:number]}>();const dialog=ref<HTMLDialogElement>();watch(()=>[props.event?.id,props.help],async()=>{await nextTick();if(props.event||props.help){if(!dialog.value?.open)dialog.value?.showModal();}else dialog.value?.close();},{immediate:true});
</script>
<template><dialog id="detail" ref="dialog" @cancel="emit('close')"><button class="dialog-close" @click="emit('close')">关闭 ×</button><div id="detailbody"><template v-if="help"><span class="eyebrow">欢迎来到七日观察室</span><h2>你改变环境，他们决定怎么生活。</h2><p>每步一个时段，一周共 28 步。动画只负责呈现，不改变模拟结果。</p><p>点击角色档案的 ☆ 关注最多三人，跟随观察持续高亮角色；关系图支持切换双方视角。</p><p>角色依据自身需求、习惯、关系和亲历信息做选择。寻找可能扑空，邀约也可能被拒绝。</p><p>改变宿舍、课程分组或举办开放日，会改变相遇条件。每天结束自动留下代表片段，为什么发生可追溯规则与历史。</p><p>每次推进与干预都会本机保存。导入会重跑校验后暂停恢复。开发需安装依赖，游玩无需模型密钥。</p></template><template v-else-if="event"><span class="eyebrow">{{event.type==='summary'?`第 ${event.data.day} 天日终`:clock(event.tick)}} / 事件 #{{event.id}}</span><h2>{{labels[event.type]}}</h2><p class="event-quote">{{event.text}}</p><h4>为什么发生</h4><p>{{event.data.reason||'世界初始化、环境变化或日终汇总。'}}</p><p v-if="event.data.delta!==undefined" class="change-pill">发起者好感 {{event.data.delta>0?'+':''}}{{event.data.delta}} · 对方好感 {{(event.data.otherDelta||0)>0?'+':''}}{{event.data.otherDelta}}</p><template v-if="event.data.scores"><h4>行动评分 · 最高分被选中</h4><div class="table-wrap"><table><thead><tr><th>候选行动</th><th>需求/目标</th><th>习惯</th><th>回避</th><th>生理负担</th><th>波动</th><th>总分</th></tr></thead><tbody><tr v-for="(s,i) in event.data.scores" :key="i"><td>{{s.action}}{{s.target!==null?` · ${world.npcs[s.target].name}`:''}}</td><td>{{s.needAndGoal}}</td><td>+{{s.habit}}</td><td>−{{s.avoidance}}</td><td>−{{s.exhaustion+s.urgentMeal}}</td><td>+{{s.noise}}</td><td>{{s.total}}</td></tr></tbody></table></div></template><template v-if="event.data.perspectives?.length"><h4>观察者视角 · 两种解释</h4><p v-for="p in event.data.perspectives" :key="p.person">{{world.npcs[p.person].name}}：{{p.interpretation}}</p></template><template v-if="event.data.observedPeople?.length"><h4>这个时段亲眼看见的人</h4><p>{{event.data.observedPeople.map(id=>world.npcs[id].name).join('、')}}</p></template><h4>此前发生了什么 · 点击继续追溯</h4><button v-for="id in event.parents" :key="id" class="memory" @click="emit('event',id)"><small>#{{id}} · {{clock(world.events[id-1].tick)}}</small>{{world.events[id-1].text}}</button><p v-if="!event.parents.length" class="empty">这是这一条因果链的起点。</p><details class="raw-data"><summary>展开规则记录</summary><pre>{{JSON.stringify(event.data,null,2)}}</pre></details></template></div></dialog></template>
